const enc = (k, v) => encodeURIComponent(k) + '=' + encodeURIComponent(v);
const chunks = ['Autophagy removes misfolded proteins from neurons.',
                'Atg7 loss caused inclusion bodies in neurons. Rapamycin restored autophagic flux.'];
const parts = [...chunks.map(c => enc('chunk_list', c)), enc('chunk_title', 'Introduction'),
               enc('chunk_title', 'Results'), enc('doc_id', 'graphvisor-diagnose')];
return [{ json: { form: parts.join('&') } }];

// One pass/fail line per check; services/diagnose.sh prints this item.
const out = (name) => { try { return $(name).first().json } catch (e) { return { error: 'did not run' } } };
const err = (j) => j.error ? String(j.error.message ?? j.error) : null;
const checks = [];
const add = (check, ok, detail, required = true) => checks.push({ check, ok, required, detail });

// The worker's own checks are reported from the host by diagnose.sh; here
// only n8n's route to the worker matters.
const w = out('Worker diagnose');
add('n8n -> worker', !err(w) && Array.isArray(w.checks),
    err(w) ?? `reached graphvisor-worker (its checks: ${w.ok ? 'passing' : 'FAILING, see the worker section'})`);

const ocr = out('OCR');
const text = String(ocr.content_parsed ?? '');
add('n8n -> OCR', !err(ocr) && /graphvisor/i.test(text),
    err(ocr) ?? (text ? `${text.length} chars: ${JSON.stringify(text.slice(0, 80))}` : 'empty content_parsed'));

const ch = out('Chunker');
const titles = ch.chunk_title ?? [], chunks = ch.chunk_list ?? [];
const chunkOk = !err(ch) && chunks.length > 0 && titles.length === chunks.length
  && titles.some(t => String(t).trim().toLowerCase() === 'abstract');
add('n8n -> chunker', chunkOk, err(ch) ?? `${chunks.length} chunks, titles ${JSON.stringify(titles)}`);

const ab = out('Abstraction');
const abstract = typeof ab.abstract === 'string' ? ab.abstract : '';
add('n8n -> abstraction', !err(ab) && abstract.length > 20,
    err(ab) ?? (abstract ? `${abstract.length} chars: ${JSON.stringify(abstract.slice(0, 80))}` : 'no abstract'));

const ol = out('Ollama');
let parsed = null;
try {
  parsed = JSON.parse(String(ol.content ?? '').replace(/<think>[\s\S]*?<\/think>/g, '')
    .trim().replace(/^```(?:json)?\s*|\s*```$/g, ''));
} catch (e) {}
add('n8n -> ollama (JSON with system prompt)', !err(ol) && parsed?.ok === true,
    err(ol) ?? `answer ${JSON.stringify(String(ol.content ?? '').slice(0, 80))}`);

return [{ json: { ok: checks.every(c => c.ok || c.required === false), checks } }];
